export function MobileDrawer({
  open = {{open}},
  edge = "{{edge}}",
  duration = {{duration}},
  accent = "{{accent}}",
}) {
  const closedX = edge === "left" ? "-100%" : "100%";
  return (
    <div style={{ position: "relative", width: "100%", maxWidth: 320, height: 140, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, overflow: "hidden", fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa" }}>
      <div className="scrim" style={{ position: "absolute", inset: 0, background: "rgba(36,20,48,.35)", opacity: open ? 1 : 0 }} />
      <nav className="panel" style={{ position: "absolute", top: 0, bottom: 0, [edge]: 0, width: "62%", padding: 16, display: "flex", flexDirection: "column", gap: 10, boxSizing: "border-box", background: accent, transform: open ? "translateX(0)" : `translateX(${closedX})` }}>
        <a href="#" style={{ color: "#FAF7F2", textDecoration: "none", fontWeight: 600 }}>Home</a>
        <a href="#" style={{ color: "#FAF7F2", textDecoration: "none", fontWeight: 600 }}>Reports</a>
        <a href="#" style={{ color: "#FAF7F2", textDecoration: "none", fontWeight: 600 }}>Settings</a>
      </nav>
      <p style={{ position: "absolute", bottom: -24, left: 0 }}>{open ? "Open" : "Closed"} &mdash; slides in from the {edge}</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .panel, .scrim { transition: transform ${duration}ms ease-out, opacity ${duration}ms ease-out; }
        }
      `}</style>
    </div>
  );
}
